package com.app.cutoff.ui.settings.fragment;
import android.os.Bundle; import android.view.View; import android.widget.*; import androidx.annotation.*; import androidx.fragment.app.Fragment; import androidx.navigation.fragment.NavHostFragment; import com.app.cutoff.R; import com.app.cutoff.utils.*; import java.util.List;
public class BankSettingsFragment extends Fragment { public BankSettingsFragment(){super(R.layout.fragment_bank_settings);} @Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){super.onViewCreated(v,s);render(v);v.findViewById(R.id.button_back).setOnClickListener(x->NavHostFragment.findNavController(this).popBackStack());v.findViewById(R.id.button_add_bank).setOnClickListener(x->{EditText input=new EditText(requireContext());input.setHint("Bank or wallet name");new com.app.cutoff.ui.common.CutoffSheetBuilder(requireContext()).setTitle("Add bank").setView(input).setPositiveButton(R.string.action_add,(d,w)->{BankPreferences.add(requireContext(),input.getText().toString());render(v);}).setNegativeButton(R.string.action_cancel,null).show();});} private void render(View root){LinearLayout list=root.findViewById(R.id.bank_list);list.removeAllViews();List<String> banks=BankPreferences.getAll(requireContext());List<String> active=BankPreferences.getActive(requireContext());for(String bank:banks){View row=getLayoutInflater().inflate(R.layout.item_bank_template,list,false);TextView name=row.findViewById(R.id.text_bank_name),status=row.findViewById(R.id.text_bank_status);Switch toggle=row.findViewById(R.id.switch_bank_active);name.setText(bank);status.setText(active.contains(bank)?"Active":"Inactive");toggle.setChecked(active.contains(bank));BankGradientUtils.apply(row.findViewById(R.id.bank_card_background),name,null,status,null,bank);toggle.setOnCheckedChangeListener((b,checked)->{BankPreferences.setActive(requireContext(),bank,checked);status.setText(checked?"Active":"Inactive");});row.findViewById(R.id.button_delete_bank).setOnClickListener(x->new com.app.cutoff.ui.common.CutoffSheetBuilder(requireContext()).setTitle("Delete bank?").setPositiveButton(android.R.string.ok,(d,w)->{BankPreferences.remove(requireContext(),bank);render(root);}).setNegativeButton(R.string.action_cancel,null).show());list.addView(row);}}}
